--
-- TOC entry 502 (class 1259 OID 74260)
-- Name: bt_sets; Type: VIEW; Schema: public; Owner: billing
--

CREATE VIEW public.bt_sets AS
 SELECT s.btse_id,
    s.partition_num,
    s.partition_date,
    s.btts_btts_id,
    s.accounting_start_date,
    s.accounting_end_date,
    s.priority,
    s.grouping_attributes_list,
    s.is_fixed,
    s.atempt_num,
    s.first_atempt_date,
    s.response_date,
    s.aggregate_date,
    s.start_after,
    s.tstrs_tstrs_id,
    s.last_rollback_bssg_id,
    s.additional_data,
    s.billing_bsst_id,
    (s.navi_date)::timestamp(0) without time zone AS start_date,
    aj.finish_date AS end_date,
    aj.error_msg AS err_msg,
    aj.ajbsg_ajbsg_id AS bssg_bssg_id,
    aj.ajbst_ajbst_id AS bsst_bsst_id,
    aj.navi_date
   FROM (public.bt_sets_tbl s
     JOIN public.async_jobs aj ON ((((aj.ext_id)::text = (s.btse_id)::text) AND (aj.ajbt_ajbt_id = ANY (ARRAY[(2)::numeric, (3)::numeric, (5)::numeric, (6)::numeric, (9)::numeric, (10)::numeric, (25)::numeric, (34)::numeric, (35)::numeric, (36)::numeric, (39)::numeric, (42)::numeric, (44)::numeric, (46)::numeric, (48)::numeric, (53)::numeric])) AND (aj.ajbst_ajbst_id <> ALL (ARRAY[(8)::numeric, (9)::numeric])) AND ((aj.partition_date = s.partition_date) OR (aj.partition_date = to_date('31.12.2300'::text, 'dd.mm.yyyy'::text))))));


ALTER VIEW public.bt_sets OWNER TO billing;

