--
-- TOC entry 501 (class 1259 OID 74252)
-- Name: bt_tasks; Type: VIEW; Schema: public; Owner: billing
--

CREATE VIEW public.bt_tasks AS
 SELECT t.btts_id,
    t.partition_date,
    t.effective_date,
    t.run_date,
    t.tstrs_tstrs_id,
    t.is_fixed,
    t.is_sets_prepared,
    t.due_date,
    t.btts_params,
    t.bttp_bttp_id,
    t.ext_order_id,
    t.rollback_btst_id,
    t.btts_billing_profile_filter,
        CASE aj.ajbst_ajbst_id
            WHEN 4 THEN (8)::numeric
            WHEN 6 THEN (5)::numeric
            WHEN 7 THEN (6)::numeric
            WHEN 10 THEN (3)::numeric
            ELSE aj.ajbst_ajbst_id
        END AS btst_btst_id,
    aj.error_msg AS err_msg,
    aj.finish_date,
    t.navi_date,
    aj.navi_user
   FROM (public.bt_tasks_tbl t
     JOIN public.async_jobs aj ON ((((aj.ext_id)::text = (t.btts_id)::text) AND (aj.ajbt_ajbt_id = ANY (ARRAY[(1)::numeric, (7)::numeric, (8)::numeric, (11)::numeric, (12)::numeric, (13)::numeric, (25)::numeric, (31)::numeric, (32)::numeric, (33)::numeric, (38)::numeric, (41)::numeric, (43)::numeric, (45)::numeric, (47)::numeric, (52)::numeric])) AND (aj.ajbst_ajbst_id <> ALL (ARRAY[(8)::numeric, (9)::numeric])) AND ((aj.partition_date = to_date(substr((t.btts_id)::text, 1, 4), 'YYMM'::text)) OR (aj.partition_date = to_date('31.12.2300'::text, 'dd.mm.yyyy'::text))))));


ALTER VIEW public.bt_tasks OWNER TO billing;

